r_check:
{
  # Parse and evaluate the candidate code in an empty environment
  env <- new.env()
  tryCatch({
    eval(parse(text = candidate), envir = env)
    # Check if 'greet' exists in the environment
    if (!exists("greet", envir = env)) {
      result <- FALSE
    } else {
      # Get the function
      f <- get("greet", envir = env)
      # Test with a specific input
      out <- tryCatch(f("Alice"), error = function(e) NA)
      if (is.na(out)) {
        result <- FALSE
      } else {
        result <- identical(out, "Hello, Alice")
      }
    }
  }, error = function(e) {
    result <- FALSE
  })
  result
}

target_val <- {
  set.seed(42)
  var(replicate(1000, mean(rnorm(5))))
}
candidate_val <- tryCatch(eval(parse(text = candidate)), error = function(e) NA)
isTRUE(!is.na(candidate_val) && abs(candidate_val - target_val) < 1e-9)

candidate <- trimws(candidate)
correct <- "x <- 1:5"
# Allow for minor whitespace variations or equivalent expressions like x <- c(1,2,3,4,5) if parsed correctly, 
# but strict string match on the canonical fix is safest for this specific prompt structure.
if (candidate == correct) {
  TRUE
} else {
  # Check if it evaluates to the same result as the correct code
  tryCatch({
    env <- new.env()
    eval(parse(text = candidate), envir = env)
    result <- env$x
    expected <- 1:5
    identical(result, expected)
  }, error = function(e) FALSE)
}
